<?php
require_once 'includes.php';
if($_SERVER['REQUEST_METHOD']==='POST'){try{$a=post('action');if($a==='allocate'){$sid=(int)post('student_id');$rid=(int)post('room_id');$date=post('allocation_date');$q=$pdo->prepare("SELECT COUNT(*) FROM allocations WHERE student_id=? AND status='Active'");$q->execute([$sid]);if((int)$q->fetchColumn()>0)throw new Exception('This student already has an active allocation.');if(active_count($pdo,$rid)>=(int)$pdo->query("SELECT capacity FROM rooms WHERE room_id=".(int)$rid)->fetchColumn())throw new Exception('This room has reached its capacity.');$q=$pdo->prepare("INSERT INTO allocations(student_id,room_id,allocation_date,status) VALUES(?,?,?,'Active')");$q->execute([$sid,$rid,$date]);flash('Room allocated successfully.');}elseif($a==='checkout'){$q=$pdo->prepare("UPDATE allocations SET status='Completed',vacating_date=? WHERE allocation_id=? AND status='Active'");$q->execute([post('vacating_date'),(int)post('id')]);flash('Check-out recorded; the bed is now available.');}}catch(Throwable $e){flash($e->getMessage(),'error');}redirect('allocations.php');}
$students=$pdo->query("SELECT student_id,student_name FROM students ORDER BY student_name")->fetchAll();
$rooms=$pdo->query("SELECT r.room_id,h.hostel_name,r.room_number,r.capacity,COUNT(a.allocation_id) occupied FROM rooms r JOIN hostels h ON h.hostel_id=r.hostel_id LEFT JOIN allocations a ON a.room_id=r.room_id AND a.status='Active' GROUP BY r.room_id HAVING occupied<r.capacity ORDER BY h.hostel_name,r.room_number")->fetchAll();
$rows=$pdo->query("SELECT a.*,s.student_name,h.hostel_name,r.room_number FROM allocations a JOIN students s ON s.student_id=a.student_id JOIN rooms r ON r.room_id=a.room_id JOIN hostels h ON h.hostel_id=r.hostel_id ORDER BY a.allocation_id DESC")->fetchAll();
page_header('Room allocations','allocations.php');?>
<section class="form-card"><h3>＋ Create room allocation</h3><?php if(!$students||!$rooms):?><p class="muted">Add students and rooms with vacant capacity before creating an allocation.</p><?php else:?><form method="post"><input type="hidden" name="action" value="allocate"><div class="form-grid"><div class="field"><label>Student</label><select name="student_id"><?php foreach($students as $s):?><option value="<?=$s['student_id']?>"><?=e($s['student_name'])?></option><?php endforeach;?></select></div><div class="field"><label>Available room</label><select name="room_id"><?php foreach($rooms as $r):?><option value="<?=$r['room_id']?>"><?=e($r['hostel_name'].' · '.$r['room_number'].' — '.($r['capacity']-$r['occupied']).' beds free')?></option><?php endforeach;?></select></div><div class="field"><label>Allocation date</label><input type="date" name="allocation_date" value="<?=date('Y-m-d')?>" required></div></div><div class="form-actions"><button class="btn">Allocate room</button></div></form><?php endif;?></section>
<h3 class="section-title">Allocation register · <?=count($rows)?></h3><div class="table-wrap"><table><thead><tr><th>ID</th><th>Student</th><th>Hostel</th><th>Room</th><th>Allocated</th><th>Vacated</th><th>Status / action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=$r['allocation_id']?></td><td><?=e($r['student_name'])?></td><td><?=e($r['hostel_name'])?></td><td><?=e($r['room_number'])?></td><td><?=e($r['allocation_date'])?></td><td><?=e($r['vacating_date']??'—')?></td><td><?php if($r['status']==='Active'):?><form class="actions" method="post"><input type="hidden" name="action" value="checkout"><input type="hidden" name="id" value="<?=$r['allocation_id']?>"><input type="date" name="vacating_date" value="<?=date('Y-m-d')?>" required style="max-width:135px;background:#0d1729;color:#fff;border:1px solid #344866;border-radius:7px;padding:6px"><button class="btn small">Check out</button></form><?php else:?><span class="badge gray"><?=e($r['status'])?></span><?php endif;?></td></tr><?php endforeach;?></tbody></table></div>
<?php page_footer();?>
